/*
 * A175612  Pairs of cousin semiprimes (m, m+4).
 * https://oeis.org/A175612
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 58, u16 n <= 58, u32 n <= 58, u64 n <= 58, u128 n <= 58,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  A175612 – Pairs of cousin semiprimes (m, m+4)
 *  a(n) = the n‑th number (duplicates allowed) in the sorted list
 *         of all semiprimes m such that both m and m+4 are semiprimes.
 *
 *  The sequence is generated by searching m in order and returning the
 *  n-th value encountered.  A simple smallest‑prime‑factor sieve is
 *  built lazily to test semiprimality.
 */

#include <stdint.h>
#include <stdlib.h>

/* Smallest prime factor table – allocated lazily.  */
static uint32_t *g_spf = NULL;   /* up to current size - 1 */
static size_t    g_spf_size = 0; /* number of entries in g_spf */

/* Extend the SPF table to at least 'limit' (inclusive).  */
static void
ensure_spf_size(size_t limit)
{
    if (g_spf_size > limit)
        return;                     /* already large enough */

    /* Allocate new memory, initialised to 0. */
    uint32_t *new_spf = (uint32_t *)calloc(limit + 1, sizeof(uint32_t));
    if (!new_spf)
        abort();                    /* out of memory */

    /* Sieve of Eratosthenes – fill smallest prime factor. */
    for (size_t i = 2; i <= limit; ++i) {
        if (new_spf[i] == 0) { /* i is prime */
            new_spf[i] = (uint32_t)i;
            if (i * i <= limit) {
                for (uint64_t j = (uint64_t)i * i; j <= limit; j += i)
                    if (new_spf[j] == 0)
                        new_spf[j] = (uint32_t)i;
            }
        }
    }

    /* Replace the old table. */
    free(g_spf);
    g_spf      = new_spf;
    g_spf_size = limit + 1;
}

/* Return 1 if x is a semiprime, 0 otherwise.  */
static int
is_semiprime(uint64_t x)
{
    if (x < 2)
        return 0;

    uint64_t t   = x;
    int      cnt = 0;

    while (t > 1) {
        /* Ensure the table is large enough.  */
        if (t >= g_spf_size)
            ensure_spf_size(t + 1000);

        uint32_t p = g_spf[(size_t)t];
        if (p == 0) {          /* t itself is prime */
            ++cnt;
            break;
        }
        ++cnt;
        t /= p;
        if (cnt > 2)           /* more than two prime factors */
            return 0;
    }
    return cnt == 2;
}

/* Main sequence function.  */
seq_t
a(idx_t n)
{
    if (n == 0)            /* undefined, return 0 in all builds */
        return (seq_t)0;

    if (g_spf == NULL)
        ensure_spf_size(1000);                 /* small starting size */

    idx_t  idx = 1;         /* current position in a(n) */
    uint64_t m = 2;         /* candidate m */

    while (1) {
        /* Make sure both m and m+4 are within the SPF table.  */
        if (m + 4 >= g_spf_size)
            ensure_spf_size(m + 4 + 1000);     /* guard space */

        if (is_semiprime(m) && is_semiprime(m + 4)) {
            if (idx == n)
                return (seq_t)m;
            ++idx;
            if (idx == n)
                return (seq_t)(m + 4);
            ++idx;
        }
        ++m;
    }
}
